function biggestGlued(nums: number[]): string {
  const parts = nums.map(String);
  let best = "";
  const used = new Array(parts.length).fill(false);
  const go = (cur: string, depth: number) => {
    if (depth === parts.length) {
      if (cur > best) best = cur; // every order has the same length
      return;
    }
    for (let i = 0; i < parts.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      go(cur + parts[i], depth + 1);
      used[i] = false;
    }
  };
  go("", 0);
  return best[0] === "0" ? "0" : best;
}

