function biggestGlued(nums: number[]): string {
  const parts = nums.map(String);
  parts.sort((a, b) => {
    const ab = a + b, ba = b + a;
    return ab > ba ? -1 : ab < ba ? 1 : 0;
  });
  return parts[0] === "0" ? "0" : parts.join("");
}

